insert into public.businesses (id, name, slug, tagline, description, services, differentiator, logo_url, cover_image_url, email, phone, show_email, show_phone, website, social_links, facility, squab_connection, status, featured, is_demo) values
  ('00000000-0000-4000-8000-001000000001', 'Forge Personal Training', 'forge-personal-training', 'Strength coaching that fits around real life.', 'Forge is a small, private training studio offering one-to-one and small-group strength coaching. Sessions are built around your goals, schedule and starting point — whether that''s moving without pain, training for an event or simply feeling stronger day to day.', array['One-to-one personal training', 'Small-group strength classes', 'Nutrition coaching', 'Pre- and post-natal training']::text[], 'No crowded gym floor: every session takes place in a quiet, fully equipped private studio with a coach who knows your plan.', null, null, 'hello@example.com', '01234 567 890', true, true, 'https://example.com', '{"instagram":"https://instagram.com/","facebook":"https://facebook.com/"}'::jsonb, 'Sample facility', 'Runs a private training studio from a ground-floor workshop unit.', 'active', true, true),
  ('00000000-0000-4000-8000-001000000002', 'The Golf Studio', 'the-golf-studio', 'Indoor coaching, custom fitting and year-round practice.', 'The Golf Studio is an indoor coaching and practice facility with launch-monitor technology, offering lessons for complete beginners through to low-handicap players. Weather never cancels a session.', array['Individual and junior lessons', 'Custom club fitting', 'Simulator practice bays', 'Corporate golf events']::text[], 'Every lesson comes with video and ball-flight data so you can see exactly what changed.', null, null, 'coach@example.com', '01234 567 891', true, true, 'https://example.com', '{"instagram":"https://instagram.com/"}'::jsonb, 'Sample facility', 'Converted a double-height industrial unit into a two-bay indoor studio.', 'active', true, true),
  ('00000000-0000-4000-8000-001000000003', 'Copper Still Gin Co.', 'copper-still-gin', 'Small-batch gin, distilled a few doors down.', 'Copper Still is an independent craft distillery producing small-batch gins and seasonal liqueurs. Everything is distilled, bottled and labelled by hand on site.', array['Signature and seasonal gins', 'Gift sets and hampers', 'Private tasting sessions', 'Corporate and wedding gifts']::text[], 'Botanicals are sourced locally wherever possible and every batch is numbered by hand.', null, null, 'orders@example.com', null, true, false, 'https://example.com', '{"instagram":"https://instagram.com/","facebook":"https://facebook.com/"}'::jsonb, 'Sample facility', 'Stores bottling stock and dry goods across two storage units.', 'active', true, true),
  ('00000000-0000-4000-8000-001000000004', 'Fieldwork Fit-Out', 'fieldwork-fit-out', 'Workspaces designed around the way your team works.', 'Fieldwork designs and delivers office and commercial fit-outs for small and growing businesses — from a single meeting room refresh to complete workspace refurbishments.', array['Space planning and design', 'Office refurbishment', 'Partitioning and ceilings', 'Furniture supply']::text[], 'One point of contact from first sketch to final snag list.', null, null, 'projects@example.com', '01234 567 893', true, true, 'https://example.com', '{"linkedin":"https://linkedin.com/"}'::jsonb, 'Sample facility', 'Operates from a first-floor office suite with materials storage below.', 'active', true, true),
  ('00000000-0000-4000-8000-001000000005', 'Grain & Joint Joinery', 'grain-and-joint-joinery', 'Bespoke joinery, made by hand in our workshop.', 'Grain & Joint is a two-person joinery workshop making bespoke furniture, fitted storage, staircases and doors for homes and businesses.', array['Fitted wardrobes and alcoves', 'Bespoke furniture', 'Staircases and doors', 'Commercial joinery']::text[], 'Every piece is designed with you and built in our own workshop — never outsourced.', null, null, 'workshop@example.com', '01234 567 894', true, true, null, '{"instagram":"https://instagram.com/"}'::jsonb, 'Sample facility', 'Runs a full joinery workshop from a light-industrial unit.', 'active', false, true),
  ('00000000-0000-4000-8000-001000000006', 'Hearth Kitchens', 'hearth-kitchens', 'Kitchen design and fitting, start to finish.', 'Hearth Kitchens designs, supplies and fits kitchens and utility rooms, with a small showroom of door styles, worktops and finishes to browse.', array['Kitchen design', 'Supply and installation', 'Worktop replacement', 'Utility rooms']::text[], 'Our own fitters handle every installation, so the team that measures is the team that fits.', null, null, 'design@example.com', '01234 567 895', true, true, 'https://example.com', '{"instagram":"https://instagram.com/","facebook":"https://facebook.com/"}'::jsonb, 'Sample facility', 'Uses a showroom unit and stores stock between installations.', 'active', false, true)
