insert into public.offers (id, business_id, title, slug, short_description, full_description, what_you_get, how_to_redeem, image_url, reward_type, reward_value, redemption_method, redemption_url, redemption_code, contact_email, contact_phone, terms, start_date, expiry_date, status, featured, is_demo, created_at, published_at) values
  ('00000000-0000-4000-8000-002000000001', '00000000-0000-4000-8000-001000000001', 'Your first session, on us', 'forge-free-introductory-session', 'A complimentary 45-minute introductory session for anyone in the Squab community.', 'Not sure whether personal training is for you? Come and try a full session with one of our coaches. We''ll talk through your goals, run a movement assessment and take you through a short workout tailored to you — with no obligation to sign up.', array['45-minute one-to-one session', 'Movement and mobility assessment', 'A simple plan to take away']::text[], 'Book online and mention Squab Connect in the notes field, then show this offer when you arrive.', null, 'introductory', 'Free intro session', 'link', 'https://example.com/book', null, null, null, 'One session per person. New clients only. Subject to availability. Sample offer for demonstration only.', '2026-10-01', '2027-03-31', 'published', true, true, '2026-10-01T09:00:00Z', '2026-10-01T09:00:00Z'),
  ('00000000-0000-4000-8000-002000000002', '00000000-0000-4000-8000-001000000002', 'Your Squab golf advantage', 'golf-studio-exclusive-coaching-rate', 'Exclusive coaching rates for the Squab community.', 'Squab customers and tenants receive an exclusive rate on individual coaching lessons at The Golf Studio, including full launch-monitor data and video analysis after every session.', array['Exclusive rate on individual lessons', 'Launch-monitor data and video', 'Personalised practice plan']::text[], 'Show this offer on your phone when you book in at the studio.', null, 'exclusive_rate', 'Exclusive offer', 'show', null, null, null, null, 'Valid on individual adult lessons only. Cannot be combined with other offers. Sample offer for demonstration only.', '2026-09-15', '2027-06-30', 'published', true, true, '2026-09-15T09:00:00Z', '2026-09-15T09:00:00Z'),
  ('00000000-0000-4000-8000-002000000003', '00000000-0000-4000-8000-001000000003', '15% off selected gins', 'copper-still-15-percent-off', 'Save 15% on our signature and seasonal gins when you order online.', 'Treat yourself — or someone else — to a bottle of small-batch gin distilled right here in the Squab community. Use the code below at checkout for 15% off selected bottles and gift sets.', array['15% off selected bottles', 'Applies to gift sets', 'Local collection available']::text[], 'Reveal the code and enter it at checkout on our website.', null, 'code', '15% off', 'code', 'https://example.com/shop', 'SQUAB15', null, null, 'Over 18s only. Excludes limited editions. One use per customer. Sample offer for demonstration only.', '2026-10-15', '2026-11-30', 'published', true, true, '2026-10-15T09:00:00Z', '2026-10-15T09:00:00Z'),
  ('00000000-0000-4000-8000-002000000004', '00000000-0000-4000-8000-001000000004', 'Complimentary workspace consultation', 'fieldwork-free-consultation', 'A free on-site consultation and outline layout for your office or unit.', 'Thinking about refreshing your workspace? We''ll visit your unit, talk through how your team works and provide an outline layout with indicative costs — completely free for Squab businesses.', array['On-site visit and measure', 'Outline layout drawing', 'Indicative budget']::text[], 'Get in touch by email or phone and mention Squab Connect.', null, 'complimentary', 'Free consultation', 'contact', null, null, 'projects@example.com', '01234 567 893', 'Available to businesses based at a Squab facility. Sample offer for demonstration only.', '2026-08-01', null, 'published', true, true, '2026-08-01T09:00:00Z', '2026-08-01T09:00:00Z'),
  ('00000000-0000-4000-8000-002000000005', '00000000-0000-4000-8000-001000000005', '£50 off fitted storage', 'grain-and-joint-50-off-fitted-storage', '£50 off any fitted wardrobe or alcove unit commission.', 'Make the most of awkward spaces with handmade fitted storage. Squab customers receive £50 off any fitted wardrobe, alcove unit or under-stairs storage commission.', array['£50 off your commission', 'Free design visit', 'Handmade in our workshop']::text[], 'Mention Squab Connect when you request a quote by email.', null, 'fixed', '£50 off', 'contact', null, null, 'workshop@example.com', null, 'Minimum order value applies. One discount per commission. Sample offer for demonstration only.', '2026-10-20', '2027-02-28', 'published', false, true, '2026-10-20T09:00:00Z', '2026-10-20T09:00:00Z'),
  ('00000000-0000-4000-8000-002000000006', '00000000-0000-4000-8000-001000000006', '10% off kitchen installation', 'hearth-kitchens-10-percent-off-installation', '10% off fitting costs when you choose a Hearth kitchen.', 'Planning a new kitchen? Squab customers receive 10% off installation when they order a kitchen through Hearth. Visit the showroom to browse door styles and worktops.', array['10% off installation', 'Free design appointment', 'Showroom visit']::text[], 'Show this offer at your design appointment.', null, 'percentage', '10% off fitting', 'show', null, null, null, null, 'Applies to installation labour only. Sample offer for demonstration only.', '2026-11-01', '2027-04-30', 'published', false, true, '2026-11-01T09:00:00Z', '2026-11-01T09:00:00Z')
