insert into public.stories (id, title, slug, standfirst, body, hero_image, hero_image_alt, author_name, category_id, format, related_business_id, status, featured, is_demo, published_at) values
  ('00000000-0000-4000-8000-003000000001', 'Meet the businesses making Squab their home', 'meet-the-businesses-making-squab-their-home', 'Behind the roller doors you''ll find distillers, joiners, coaches and designers. Here''s a first look at the community taking shape.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk the corridors of any Squab facility and you''ll quickly realise it is much more than a place to keep things. It''s a place where people "},{"type":"text","text":"build","marks":[{"type":"italic"}]},{"type":"text","text":" things — businesses, products, careers and, increasingly, relationships with each other."}]},{"type":"paragraph","content":[{"type":"text","text":"Squab Connect exists to make those relationships easier to find. Over the coming months we''ll be introducing the people behind the units, sharing what they do and helping the rest of the community discover them."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A surprisingly diverse mix"}]},{"type":"paragraph","content":[{"type":"text","text":"Our (sample) line-up already includes a personal training studio, an indoor golf studio, a small-batch gin distillery, an office fit-out company, a joinery workshop and a kitchen fitter. Each one chose Squab for different reasons — flexible space, room to grow or simply a convenient place to run a business."}]},{"type":"image","attrs":{"alt":"Placeholder: a workshop interior","caption":"Real photography of Squab tenants will replace this placeholder."}},{"type":"pullQuote","attrs":{"text":"Good things happen when the businesses around you know what you do.","cite":"The Squab Connect team"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How you can take part"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Browse the directory","marks":[{"type":"bold"}]},{"type":"text","text":" to see who''s based near you."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check Squab Perks","marks":[{"type":"bold"}]},{"type":"text","text":" for exclusive offers from fellow tenants."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Come to an event","marks":[{"type":"bold"}]},{"type":"text","text":" and meet people face to face."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"If you run a business from Squab and would like to be featured, "},{"type":"text","text":"get in touch","marks":[{"type":"link","attrs":{"href":"/about"}}]},{"type":"text","text":" — we''d love to hear from you."}]},{"type":"ctaButton","attrs":{"label":"Explore the directory","href":"/businesses"}}]}'::jsonb, null, 'Placeholder: tenants outside their units', 'The Squab Connect team', '00000000-0000-4000-8000-000300000001', 'standard', null, 'published', true, true, '2026-11-03T08:00:00Z'),
  ('00000000-0000-4000-8000-003000000002', 'Meet Copper Still: the distillery a few doors down', 'business-spotlight-copper-still-gin', 'How a weekend hobby turned into a small-batch distillery — and why the founders chose to grow at Squab.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is a sample business spotlight used to demonstrate the format. The business and quotes are fictional.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What the business does"}]},{"type":"paragraph","content":[{"type":"text","text":"Copper Still produces small-batch gins and seasonal liqueurs, distilled, bottled and labelled by hand. Their range is sold online, at local markets and through a handful of independent shops."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How it started"}]},{"type":"paragraph","content":[{"type":"text","text":"Like many good ideas, it began at a kitchen table. A few experimental batches for friends became a market stall, which became a licence, which became a proper still — and suddenly there wasn''t room at home any more."}]},{"type":"pullQuote","attrs":{"text":"We needed somewhere flexible that could grow with us. Starting with one unit and adding a second when we needed it made all the difference.","cite":"Founder, Copper Still (sample quote)"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What makes it different"}]},{"type":"paragraph","content":[{"type":"text","text":"Botanicals are sourced locally wherever possible, and every batch is numbered by hand so customers know exactly which run their bottle came from."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What''s next"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A winter spiced edition"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Monthly tasting evenings"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A trade range for local hospitality"}]}]}]},{"type":"ctaButton","attrs":{"label":"View Copper Still''s profile","href":"/businesses/copper-still-gin"}}]}'::jsonb, null, 'Placeholder: copper still and bottles', 'The Squab Connect team', '00000000-0000-4000-8000-000300000002', 'spotlight', '00000000-0000-4000-8000-001000000003', 'published', false, true, '2026-10-28T08:00:00Z'),
  ('00000000-0000-4000-8000-003000000003', 'What''s happening across Squab this month', 'whats-happening-across-squab-this-month', 'New faces, improvements on site and the date for our next networking evening.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sample news round-up for demonstration purposes.","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Welcome to our newest tenants"}]},{"type":"paragraph","content":[{"type":"text","text":"We''ve welcomed several new businesses this month. You''ll find them in the directory as their profiles go live."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"On-site improvements"}]},{"type":"paragraph","content":[{"type":"text","text":"Updates to facilities and access will be announced here and in the Squab Connect newsletter."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Save the date"}]},{"type":"paragraph","content":[{"type":"text","text":"Our next networking evening is coming up soon — see the events page for details and registration."}]},{"type":"ctaButton","attrs":{"label":"See upcoming events","href":"/events"}}]}'::jsonb, null, 'Placeholder: Squab facility exterior', 'The Squab Connect team', '00000000-0000-4000-8000-000300000003', 'standard', null, 'published', false, true, '2026-11-01T08:00:00Z'),
  ('00000000-0000-4000-8000-003000000004', 'Join us at our next networking evening', 'join-us-at-our-next-networking-evening', 'Drinks, introductions and a chance to meet the businesses around you — no name-badge awkwardness required.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Our networking evenings are relaxed, informal and open to every business and customer in the Squab community."}]},{"type":"paragraph","content":[{"type":"text","text":"Expect short introductions from a few tenant businesses, plenty of time to chat and some (sample) local drinks."}]},{"type":"ctaButton","attrs":{"label":"Register for the evening","href":"/events/autumn-networking-evening"}}]}'::jsonb, null, 'Placeholder: people chatting at an evening event', 'The Squab Connect team', '00000000-0000-4000-8000-000300000004', 'standard', null, 'published', false, true, '2026-10-22T08:00:00Z'),
  ('00000000-0000-4000-8000-003000000005', 'Five practical ways to make a small unit work harder', 'five-ways-to-make-a-small-unit-work-harder', 'Advice from the joiners and fit-out specialists in our community on getting more from every square metre.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sample insight article for demonstration purposes.","marks":[{"type":"italic"}]}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go vertical.","marks":[{"type":"bold"}]},{"type":"text","text":" Full-height shelving often doubles usable storage."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Zone the space.","marks":[{"type":"bold"}]},{"type":"text","text":" Separate making, storing and admin areas, even with tape on the floor."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Light it properly.","marks":[{"type":"bold"}]},{"type":"text","text":" Good task lighting is the cheapest productivity upgrade there is."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Plan for deliveries.","marks":[{"type":"bold"}]},{"type":"text","text":" Keep the area nearest the door clear for goods in and out."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review every six months.","marks":[{"type":"bold"}]},{"type":"text","text":" Your needs change — your layout should too."}]}]}]},{"type":"ctaButton","attrs":{"label":"Book a free workspace consultation","href":"/perks/fieldwork-free-consultation"}}]}'::jsonb, null, 'Placeholder: organised workshop shelving', 'The Squab Connect team', '00000000-0000-4000-8000-000300000005', 'standard', '00000000-0000-4000-8000-001000000004', 'published', false, true, '2026-10-15T08:00:00Z')
insert into public.events (id, title, slug, summary, description, what_to_expect, who_should_attend, image_url, start_datetime, end_datetime, venue, address, registration_url, contact_email, capacity, fully_booked, status, featured, is_demo) values
  ('00000000-0000-4000-8000-004000000001', 'Autumn Networking Evening', 'autumn-networking-evening', 'An informal evening of drinks, introductions and conversation with businesses from across the Squab community.', 'Join us for a relaxed evening designed to help you meet the people and businesses working alongside you.
