insert into public.site_settings (key, value) values
  ('homepage', '{"hero":{"eyebrow":"Welcome to Squab Connect","headline":"Good things happen when we connect.","subheading":"Discover exclusive offers, meet the businesses around you and stay up to date with everything happening across the Squab community.","primaryCta":{"label":"Explore Squab Perks","href":"/perks"},"secondaryCta":{"label":"Discover our community","href":"/businesses"}},"community":{"headline":"Part of the Squab community? Make yourself known.","body":"Whether you have a business to promote, an offer to share or simply want to meet the people around you, Squab Connect is the place to start.","cta":{"label":"Find out more","href":"/about"}}}'::jsonb)
